-- Migration sugerida: criar tabela oficial para plano/acesso dos clientes
-- Revise antes de rodar em produção.

create table if not exists public.client_access (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  plan text not null check (plan in ('free', 'premium')),
  status text not null default 'active',
  source_roles text,
  source_plan_id uuid null,
  migrated_from text not null default 'clientes-2026-07-01.json',
  created_at timestamp with time zone default now(),
  updated_at timestamp with time zone default now(),
  constraint client_access_user_id_unique unique (user_id)
);

